// pdfkit 0.20 added these for its browser build (the one a Worker gets); @types/pdfkit predates them.
declare module "pdfkit/standard-fonts/Helvetica" {
  const font: unknown;
  export default font;
}
declare module "pdfkit/standard-fonts/HelveticaBold" {
  const font: unknown;
  export default font;
}
declare module "pdfkit/standard-fonts/HelveticaBoldOblique" {
  const font: unknown;
  export default font;
}
declare module "pdfkit/standard-fonts/HelveticaOblique" {
  const font: unknown;
  export default font;
}
